function explicitAgeFromText() {
  const match = String(rawText || '').match(/\b(?:tenho|tem|idade\s*(?:é|e)?|com)\s*(\d{1,2})\s*anos?\b/i);
  if (!match) return null;
  const age = Number(match[1]);
  return Number.isFinite(age) ? age : null;
}

function matchKeywords(keywords = []) {
  return asArray(keywords).some((keyword) => normalized.includes(normalizeText(keyword)));
}

function isPureGreeting() {
  // V4.5.1:
  // Não tentamos mais classificar saudações por regex/whitelist.
  // Linguagem natural (oi, coé, salve, fala tu, qual a boa, etc.)
  // deve ser interpretada semanticamente pelo Gemini.
  // Mantemos somente /start como comando estrutural conhecido.
  const compact = normalizeText(rawText)
    .replace(/[^\w\s/]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return compact === '/start';
}

function todayKey() {
  return new Date().toISOString().slice(0, 10);
}

function httpHeaderValue(headers, name) {
  if (!headers) return '';
  if (typeof headers.get === 'function') return String(headers.get(name) || headers.get(name.toLowerCase()) || '');
  const key = Object.keys(headers).find(item => item.toLowerCase() === name.toLowerCase());
  const value = key ? headers[key] : '';
  return Array.isArray(value) ? String(value[0] || '') : String(value || '');
}

function httpErrorHeaders(error) {
  const candidates=[error?.cause?.response?.headers,error?.response?.headers,error?.context?.headers,
    error?.error?.response?.headers,error?.headers,error?.cause?.headers];
  for(const headers of candidates){
    if(!headers||typeof headers!=='object')continue;
    if(typeof headers.get==='function'||Object.keys(headers).length)return headers;
  }
  return {};
}

function httpProviderBody(error) {
  const candidates = [
    error?.response?.data,
    error?.response?.body,
    error?.cause?.response?.data,
    error?.cause?.response?.body,
    error?.cause?.data,
    error?.cause?.body,
    error?.context?.data,
    error?.context?.body,
    error?.body,
    error?.data,
    error?.error?.response?.data,
    error?.error?.response?.body,
    error?.error?.body,
  ];
  let fallback = null;
  const unwrap = raw => {
    if (!raw) return null;
    if (typeof Buffer !== 'undefined' && Buffer.isBuffer(raw)) return unwrap(raw.toString('utf8'));
    if (typeof raw === 'string') {
      const value = raw.trim();
      if (!value || value.length > 100000) return null;
      if (value.startsWith('{') || value.startsWith('[')) {
        try { return unwrap(JSON.parse(value)); } catch (_) {}
      }
      const match = value.match(/\{[\s\S]*"error"\s*:\s*\{[\s\S]*\}[\s\S]*\}/);
      if (match) { try { return unwrap(JSON.parse(match[0])); } catch (_) {} }
      return null;
    }
    if (Array.isArray(raw)) {
      for (const item of raw) { const parsed = unwrap(item); if (parsed?.error) return parsed; }
      return null;
    }
    if (typeof raw === 'object') {
      if (!Object.keys(raw).length) return null;
      if (raw.error && typeof raw.error === 'object') return raw;
      const nested = unwrap(raw.data) || unwrap(raw.body);
      if (nested?.error) return nested;
      return raw;
    }
    return null;
  };
  for (const raw of candidates) {
    const parsed = unwrap(raw);
    if (parsed?.error) return parsed;
    if (parsed && !fallback) fallback = parsed;
  }
  for (const text of [error?.description, error?.message, error?.cause?.message]) {
    if (typeof text === 'string') {
      const match = text.match(/\{[\s\S]*"error"[\s\S]*\}/);
      if (match) {
        try { const parsed = unwrap(JSON.parse(match[0])); if (parsed) return parsed; } catch (_) {}
      }
    }
  }
  return fallback || {};
}

function httpDurationMs(value) {
  const text = String(value ?? '').trim();
  if (!text) return null;
  const match = text.match(/^(\d+(?:\.\d+)?)(ms|s)?$/i);
  if (!match) return null;
  return Math.max(0, Math.ceil(Number(match[1]) * (match[2]?.toLowerCase() === 'ms' ? 1 : 1000)));
}

function httpRetryAfterMs(headers, details = [], now = Date.now()) {
  const value = httpHeaderValue(headers, 'retry-after').trim();
  if (value) {
    if (/^\d+(?:\.\d+)?$/.test(value)) return Math.max(0, Math.ceil(Number(value) * 1000));
    const at = Date.parse(value);
    if (Number.isFinite(at)) return Math.max(0, at - now);
  }
  for (const detail of Array.isArray(details) ? details : []) {
    const parsed = httpDurationMs(detail?.retryDelay ?? detail?.retry_delay ?? detail?.metadata?.retryDelay);
    if (parsed !== null) return parsed;
  }
  return null;
}

function httpSafeDiagnostic(error, metadata = {}) {
  const body = httpProviderBody(error);
  const providerError = body?.error && typeof body.error === 'object' ? body.error : {};
  const headers = httpErrorHeaders(error);
  const rawStatus = error?.statusCode ?? error?.status ?? error?.httpCode ?? error?.response?.statusCode
    ?? error?.response?.status ?? error?.cause?.response?.statusCode ?? error?.cause?.response?.status
    ?? error?.cause?.statusCode ?? error?.cause?.status ?? error?.context?.statusCode
    ?? providerError.code ?? null;
  let numericStatus = Number(rawStatus);
  if (!Number.isInteger(numericStatus) || numericStatus < 100 || numericStatus > 599) {
    const msgMatch = String(error?.message || '').match(/\b([1-5]\d\d)\b/);
    if (msgMatch) numericStatus = Number(msgMatch[1]);
  }
  const httpStatus = Number.isInteger(numericStatus) && numericStatus >= 100 && numericStatus <= 599 ? numericStatus : null;
  const providerCode = Number.isInteger(Number(providerError.code)) ? Number(providerError.code) : null;
  const providerStatus = /^[A-Z][A-Z0-9_]{1,80}$/.test(String(providerError.status || ''))
    ? String(providerError.status) : null;
  const networkCandidate = String(error?.code || error?.cause?.code || '').toUpperCase();
  const networkCode = /^(?:ETIMEDOUT|ESOCKETTIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ABORT_ERR)$/.test(networkCandidate)
    ? networkCandidate : null;
  const message = [error?.message,error?.description,providerError?.message].filter(Boolean).join(' ').toLowerCase();
  let category = 'unknown';
  if (httpStatus === 429 || providerStatus === 'RESOURCE_EXHAUSTED' || /quota|resource has been exhausted|too many requests/i.test(message)) category = 'rate_limit';
  else if (httpStatus === 401 || providerStatus === 'UNAUTHENTICATED') category = 'authentication';
  else if (httpStatus === 403 || providerStatus === 'PERMISSION_DENIED') category = /quota|billing|exceeded/i.test(message)?'rate_limit':'permission';
  else if (httpStatus === 404 || providerStatus === 'NOT_FOUND') category = 'model_unavailable';
  else if (httpStatus === 400 || providerStatus === 'INVALID_ARGUMENT') category = 'invalid_request_or_schema';
  else if (httpStatus && httpStatus >= 500) category = 'upstream_server';
  else if (networkCode || /timeout|timed out|socket hang up/.test(message)) category = 'network_or_timeout';

  const details = Array.isArray(providerError.details) ? providerError.details : [];
  const retryAfterMs = httpRetryAfterMs(headers, details);
  const requestId = httpHeaderValue(headers, 'x-goog-request-id') || httpHeaderValue(headers, 'x-request-id') || null;
  const quotaMetrics = [...new Set(details.flatMap(detail => {
    const violations = Array.isArray(detail?.violations) ? detail.violations : [];
    return [detail?.quotaMetric || detail?.quotaId || detail?.metadata?.quota_metric,
      ...violations.map(item => item?.quotaMetric || item?.quotaId || item?.subject)]
      .map(item => String(item || '').slice(0, 180)).filter(Boolean);
  }))].slice(0, 8);
  const metricsText = (quotaMetrics.join(' ') + ' ' + message).toLowerCase();
  const limitDimension = category !== 'rate_limit' ? null
    : /per_day|requests_per_day|rpd/.test(metricsText) ? 'rpd'
    : /token|tokens_per_minute|tpm/.test(metricsText) ? 'tpm'
    : /per_minute|requests_per_minute|rpm/.test(metricsText) ? 'rpm'
    : 'unspecified_quota';
  return {
    category,
    http_status: httpStatus,
    provider_code: providerCode,
    provider_status: providerStatus,
    network_code: networkCode,
    model: metadata.model || null,
    operation: metadata.operation || 'http_request',
    duration_ms: Number(metadata.duration_ms || 0),
    attempts: Number(metadata.attempts || 1),
    retryable: ['rate_limit', 'upstream_server', 'network_or_timeout'].includes(category)
      && !['rpd'].includes(limitDimension),
    retry_after_ms: retryAfterMs,
    provider_request_id: requestId ? String(requestId).slice(0, 180) : null,
    quota_metrics: quotaMetrics,
    ...(limitDimension ? { limit_dimension: limitDimension } : {}),
    ...(metadata.rate_control_mode ? { rate_control_mode: metadata.rate_control_mode } : {}),
  };
}

function getSharedRuntimeState() {
  try {
    if (typeof $getWorkflowStaticData === 'function') {
      return $getWorkflowStaticData('global');
    }
  } catch (_) {}
  if (typeof globalThis !== 'undefined') {
    return globalThis.__NORIA_SHARED_RUNTIME__ || (globalThis.__NORIA_SHARED_RUNTIME__ = {});
  }
  return {};
}

function geminiRateConfig() {
  const scope = String(env('GEMINI_RATE_SCOPE', '') || '').trim();
  const maxRpm = Number(env('GEMINI_MAX_RPM', '0'));
  const maxTpm = Number(env('GEMINI_MAX_TPM', '0'));
  const maxRpd = Number(env('GEMINI_MAX_RPD', '0'));
  const required = String(env('GEMINI_RATE_CONTROL_REQUIRED', 'false')).toLowerCase() === 'true';
  const distributed = /^[a-zA-Z0-9._:-]{1,120}$/.test(scope)
    && [maxRpm, maxTpm, maxRpd].every(value => Number.isFinite(value) && value > 0);
  return { scope, maxRpm, maxTpm, maxRpd, required, distributed };
}

function estimateGeminiTokens(payload) {
  try {
    const chars = JSON.stringify(payload || {}).length;
    const output = Number(payload?.generationConfig?.maxOutputTokens || 512);
    return Math.max(1, Math.ceil(chars / 3.5) + Math.min(Math.max(output, 1), 8192));
  } catch (_) { return 1000; }
}

async function geminiRateRpc(name, body) {
  const base = String(env('SUPABASE_URL', '') || '').replace(/\/$/, '');
  const key = String(env('SUPABASE_SERVICE_ROLE_KEY', '') || '');
  if (!base || !key) throw new Error('GEMINI_RATE_CONTROL_DATABASE_UNAVAILABLE');
  return helpers.httpRequest({method:'POST',url:base+'/rest/v1/rpc/'+name,
    headers:{apikey:key,Authorization:'Bearer '+key,'Content-Type':'application/json'},
    body,json:true,timeout:3000});
}

function geminiControlError(reason, retryAfterMs = null, model = null, mode = 'supabase_atomic') {
  const internalLimit = ['rpm_exceeded','tpm_exceeded','rpd_exceeded'].includes(reason);
  const circuit = ['circuit_open','half_open_busy','probe_timeout_cooldown','local_half_open_busy'].includes(reason);
  const concurrency = reason === 'concurrency_busy';
  const error = new Error(internalLimit ? 'GEMINI_INTERNAL_RATE_LIMIT'
    : circuit ? 'GEMINI_CIRCUIT_OPEN'
    : concurrency ? 'GEMINI_CONCURRENCY_BUSY' : 'GEMINI_RATE_CONTROL_UNAVAILABLE');
  error.diagnostic = {
    category: internalLimit ? 'internal_rate_limit' : circuit ? 'circuit_breaker'
      : concurrency ? 'local_backpressure' : 'rate_control_unavailable',
    http_status: null, provider_status: null, provider_code: null, model,
    operation: 'rate_control', duration_ms: 0, attempts: 0, retryable: false,
    retry_after_ms: Number.isFinite(Number(retryAfterMs)) ? Number(retryAfterMs) : null,
    quota_metrics: [], reason, rate_control_mode: mode,
  };
  return error;
}

function checkGeminiCircuitBreaker(model = null) {
  const shared = getSharedRuntimeState();
  const openUntil = Number(shared.gemini_circuit_open_until || 0);
  const now = Date.now();
  if (openUntil > now) {
    const waitMs = openUntil - now;
    const error = new Error('GEMINI_RATE_LIMIT');
    error.diagnostic = {
      category: 'rate_limit',
      http_status: null,
      provider_status: null,
      provider_code: null,
      model,
      operation: 'circuit_breaker',
      duration_ms: 0,
      attempts: 0,
      retryable: false,
      retry_after_ms: waitMs,
      quota_metrics: shared.gemini_circuit_quota_metrics || [],
      reason: 'local_circuit_breaker_active',
      rate_control_mode: 'local_fallback'
    };
    return error;
  }
  if (openUntil > 0 && Number(shared.gemini_probe_until || 0) > now) {
    return geminiControlError('local_half_open_busy', Number(shared.gemini_probe_until)-now, model, 'local_fallback');
  }
  return null;
}

function recordGeminiCircuitFailure(diagnostic) {
  if (diagnostic?.category !== 'rate_limit') return;
  const shared = getSharedRuntimeState();
  const cooldownMs = Number(env('GEMINI_CIRCUIT_COOLDOWN_MS', '30000'));
  const waitMs = Math.max(1000, Number(diagnostic.retry_after_ms) || cooldownMs);
  shared.gemini_circuit_open_until = Date.now() + Math.min(waitMs, 300000);
  shared.gemini_probe_id = '';
  shared.gemini_probe_until = 0;
  if (Array.isArray(diagnostic.quota_metrics) && diagnostic.quota_metrics.length > 0) {
    shared.gemini_circuit_quota_metrics = diagnostic.quota_metrics;
  }
}

function recordGeminiSuccess(lease = null) {
  const shared = getSharedRuntimeState();
  if (lease?.is_probe && shared.gemini_probe_id === lease.lease_id) {
    shared.gemini_circuit_open_until = 0;
    shared.gemini_probe_id = '';
    shared.gemini_probe_until = 0;
  }
}

async function acquireGeminiConcurrencySlot(options = {}) {
  const config = geminiRateConfig();
  const model = String(options.model || 'default');
  const leaseTtlMs = Math.max(20000, Math.min(Number(env('GEMINI_LEASE_TTL_MS', '30000')) || 30000, 120000));
  const probeCooldownMs = Math.max(1000, Math.min(Number(env('GEMINI_CIRCUIT_COOLDOWN_MS', '30000')) || 30000, 300000));
  const leaseId = String((turn?.token || chatId || 'call') + ':' + Date.now() + ':' + Math.random().toString(36).slice(2, 12));
  if (config.distributed) {
    let result;
    try {
      result = await geminiRateRpc('magia_gemini_acquire', {
        p_scope:config.scope,p_model:model,p_lease_id:leaseId,
        p_estimated_tokens:Math.max(1,Math.ceil(Number(options.estimatedTokens)||1000)),
        p_max_concurrent:Math.max(1,Math.min(Number(env('GEMINI_MAX_CONCURRENT_CALLS','2'))||2,20)),
        p_max_rpm:config.maxRpm,p_max_tpm:config.maxTpm,p_max_rpd:config.maxRpd,
        p_lease_ttl_ms:leaseTtlMs,p_probe_cooldown_ms:probeCooldownMs,
      });
    } catch (_) {
      if (config.required) throw geminiControlError('distributed_controller_unavailable', null, model);
      result = null;
    }
    if (result) {
      if (result.allowed !== true) throw geminiControlError(String(result.reason||'denied'),result.retry_after_ms,model);
      return {mode:'supabase_atomic',scope:config.scope,model,lease_id:leaseId,
        generation:Number(result.generation||0),is_probe:result.is_probe===true,lease_ttl_ms:leaseTtlMs};
    }
  } else if (config.required) {
    throw geminiControlError('distributed_controller_not_configured', null, model, 'unconfigured');
  }

  const shared = getSharedRuntimeState();
  const configuredMax = Number(env('GEMINI_MAX_CONCURRENT_CALLS', '2'));
  const maxConcurrent = Math.max(1, Math.min(Number.isFinite(configuredMax) ? configuredMax : 2, 20));
  const configuredWaitMs = Number(env('GEMINI_CONCURRENCY_WAIT_MS', '12000'));
  const maxWaitMs = Math.max(250, Math.min(Number.isFinite(configuredWaitMs) ? configuredWaitMs : 12000, 30000));
  const started = Date.now();
  while (Math.max(0, Number(shared.gemini_active_calls) || 0) >= maxConcurrent) {
    const circuitError = checkGeminiCircuitBreaker();
    if (circuitError) throw circuitError;
    if (Date.now() - started >= maxWaitMs) {
      const error = new Error('GEMINI_CONCURRENCY_BUSY');
      error.diagnostic = {
        category: 'local_backpressure',
        http_status: null,
        provider_status: null,
        provider_code: null,
        model: null,
        operation: 'concurrency_limiter',
        duration_ms: Date.now() - started,
        attempts: 0,
        retryable: false,
        retry_after_ms: null,
        quota_metrics: [],
        reason: 'concurrency_wait_exhausted'
      };
      throw error;
    }
    await new Promise(r => setTimeout(r, 40 + Math.floor(Math.random() * 30)));
  }
  let isProbe=false;
  if (Number(shared.gemini_circuit_open_until||0)>0
      && Number(shared.gemini_circuit_open_until)<=Date.now()) {
    if (Number(shared.gemini_probe_until||0)>Date.now()) {
      throw geminiControlError('local_half_open_busy',Number(shared.gemini_probe_until)-Date.now(),model,'local_fallback');
    }
    isProbe=true;
    shared.gemini_probe_id=leaseId;
    shared.gemini_probe_until=Date.now()+leaseTtlMs;
  }
  shared.gemini_active_calls = Math.max(0, Number(shared.gemini_active_calls) || 0) + 1;
  return {mode:config.distributed?'distributed_unavailable_local_fallback':'local_only_unconfigured',model,
    lease_id:leaseId,is_probe:isProbe,lease_ttl_ms:leaseTtlMs};
}

async function releaseGeminiConcurrencySlot(lease, outcome = 'released', diagnostic = null) {
  if (lease?.mode === 'supabase_atomic') {
    const mapped = outcome === 'success' ? 'success'
      : diagnostic?.category === 'rate_limit' ? 'rate_limit'
      : diagnostic?.category === 'upstream_server' ? 'upstream_server'
      : diagnostic?.category === 'network_or_timeout' ? 'network_or_timeout' : 'released';
    try {
      await geminiRateRpc('magia_gemini_release', {p_scope:lease.scope,p_model:lease.model,
        p_lease_id:lease.lease_id,p_outcome:mapped,
        p_cooldown_ms:Math.max(1000,Math.min(Number(diagnostic?.retry_after_ms)||Number(env('GEMINI_CIRCUIT_COOLDOWN_MS','30000'))||30000,300000))});
    } catch (_) {}
    return;
  }
  const shared = getSharedRuntimeState();
  shared.gemini_active_calls = Math.max(0, (shared.gemini_active_calls || 1) - 1);
  if (lease?.is_probe && outcome !== 'success' && shared.gemini_probe_id === lease.lease_id) {
    const cooldownMs = Math.max(1000, Math.min(Number(diagnostic?.retry_after_ms)
      || Number(env('GEMINI_CIRCUIT_COOLDOWN_MS','30000')) || 30000, 300000));
    shared.gemini_circuit_open_until = Date.now() + cooldownMs;
    shared.gemini_probe_id = '';
    shared.gemini_probe_until = 0;
  }
}

function httpGeminiMetadata(url, payload, options = {}) {
  const match = String(url || '').match(/\/models\/([^/:?]+):/);
  const instruction = String(payload?.system_instruction?.parts?.[0]?.text || '');
  let operation = options.operation || 'gemini_generate';
  if (instruction.startsWith('NORIA_DIALOGUE_PLAN')) operation = 'dialogue_plan';
  else if (instruction.startsWith('NORIA_DIALOGUE_WRITE')) operation = 'dialogue_compose';
  else if (instruction.startsWith('NORIA_DIALOGUE_AUDIT')) operation = 'dialogue_audit';
  else if (payload?.contents?.some?.(content => content?.parts?.some?.(part => part?.inlineData))) operation = 'gemini_media';
  return { model: options.model || match?.[1] || null, operation };
}

async function httpJson(method, url, headers = {}, payload = null, options = {}) {
  const isGemini = /^https:\/\/generativelanguage\.googleapis\.com\//.test(String(url || ''));
  if (isGemini) {
    const circuitError = checkGeminiCircuitBreaker();
    if (circuitError) throw circuitError;
  }
  const metadata = isGemini ? httpGeminiMetadata(url, payload, options) : { model: null, operation: options.operation || 'http_request' };
  const configuredAttempts = Number(env('GEMINI_RETRY_MAX_ATTEMPTS', '2'));
  const maxAttempts = isGemini && options.retry !== false
    ? Math.max(1, Math.min(Number.isFinite(configuredAttempts) ? configuredAttempts : 2, 3)) : 1;
  const totalBudgetMs = isGemini ? 12000 : 0;
  const startedAt = Date.now();
  let lastDiagnostic = null;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    const callStartedAt = Date.now();
    let lease = null;
    try {
      if (isGemini) {
        const circuitError = checkGeminiCircuitBreaker(metadata.model);
        if (circuitError) throw circuitError;
        lease = await acquireGeminiConcurrencySlot({model:metadata.model,estimatedTokens:estimateGeminiTokens(payload)});
        markGeminiPhysicalUsage();
      }
      const response = await helpers.httpRequest({
        method,
        url,
        headers,
        ...(payload === null ? {} : { body: payload }),
        json: true,
        timeout: isGemini ? Math.max(1000, Math.min(15000, totalBudgetMs - (Date.now() - startedAt))) : 45000,
      });
      if (isGemini) {
        const completedLease=lease;
        await releaseGeminiConcurrencySlot(completedLease, 'success');
        recordGeminiSuccess(completedLease);
        lease = null;
      }
      return response;
    } catch (error) {
      if (!isGemini) throw error;
      lastDiagnostic = error?.diagnostic && typeof error.diagnostic === 'object'
        ? { ...error.diagnostic, model: error.diagnostic.model || metadata.model,
          operation: error.diagnostic.operation || metadata.operation,
          rate_control_mode:error.diagnostic.rate_control_mode||lease?.mode||'none',
          duration_ms: Number(error.diagnostic.duration_ms || Date.now() - callStartedAt), attempts: attempt }
        : httpSafeDiagnostic(error, {
          ...metadata,
          duration_ms: Date.now() - callStartedAt,
          attempts: attempt,rate_control_mode:lease?.mode||'none',
         });
      if (lease) {
        await releaseGeminiConcurrencySlot(lease, 'failure', lastDiagnostic);
        lease = null;
      }
      if (lastDiagnostic.category === 'rate_limit') {
        recordGeminiCircuitFailure(lastDiagnostic);
      }
      const elapsed = Date.now() - startedAt;
      if (lastDiagnostic.reason === 'local_circuit_breaker_active'
          || lastDiagnostic.category === 'circuit_breaker'
          || lastDiagnostic.category === 'internal_rate_limit'
          || lastDiagnostic.category === 'rate_control_unavailable'
          || !lastDiagnostic.retryable || attempt >= maxAttempts || elapsed >= totalBudgetMs) {
        const wrapped = new Error(lastDiagnostic.category === 'rate_limit' ? 'GEMINI_RATE_LIMIT'
          : lastDiagnostic.category === 'internal_rate_limit' ? 'GEMINI_INTERNAL_RATE_LIMIT'
          : lastDiagnostic.category === 'circuit_breaker' ? 'GEMINI_CIRCUIT_OPEN'
          : lastDiagnostic.category === 'rate_control_unavailable' ? 'GEMINI_RATE_CONTROL_UNAVAILABLE'
          : lastDiagnostic.category === 'local_backpressure' ? 'GEMINI_CONCURRENCY_BUSY'
          : lastDiagnostic.category === 'authentication' ? 'GEMINI_AUTHENTICATION_FAILED'
          : lastDiagnostic.category === 'permission' ? 'GEMINI_PERMISSION_DENIED'
          : lastDiagnostic.category === 'model_unavailable' ? 'GEMINI_MODEL_UNAVAILABLE'
          : lastDiagnostic.category === 'invalid_request_or_schema' ? 'GEMINI_INVALID_REQUEST'
          : lastDiagnostic.category === 'upstream_server' ? 'GEMINI_UPSTREAM_UNAVAILABLE'
          : lastDiagnostic.category === 'network_or_timeout' ? 'GEMINI_NETWORK_OR_TIMEOUT'
          : 'HTTP_REQUEST_FAILED');
        wrapped.diagnostic = lastDiagnostic;
        throw wrapped;
      }
      const baseDelay = Math.min(250 * (2 ** (attempt - 1)), 2000);
      const jitter = Math.floor(Math.random() * Math.max(50, Math.floor(baseDelay * 0.25)));
      const requestedDelay = lastDiagnostic.retry_after_ms === null ? baseDelay + jitter : lastDiagnostic.retry_after_ms;
      const remaining = totalBudgetMs - elapsed;
      if (requestedDelay > remaining) {
        const wrapped = new Error(lastDiagnostic.category === 'rate_limit' ? 'GEMINI_RATE_LIMIT' : 'GEMINI_RETRY_BUDGET_EXHAUSTED');
        wrapped.diagnostic = lastDiagnostic;
        throw wrapped;
      }
      await new Promise(resolve => setTimeout(resolve, requestedDelay));
    }
  }
  const wrapped = new Error('HTTP_REQUEST_FAILED');
  wrapped.diagnostic = lastDiagnostic;
  throw wrapped;
}

function mediaError(message, code = 'media_processing_error') {
  const error = new Error(message);
  error.code = code;
  return error;
}

function tenantEnvSuffix(value) {
  return String(value || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '_');
}

function telegramTokenFor(context = {}) {
  const channel = context.channel || {};
  const channelConfig = channel.config || channel.settings || {};

  // Compatível com a convenção já usada no magia_command_router.json:
  // TELEGRAM_BOT_TOKEN_<TENANT_SLUG>
  const tenantToken = env(
    'TELEGRAM_BOT_TOKEN_' + tenantEnvSuffix(tenantSlug)
  );

  // Também aceita um env customizado cadastrado no channel, caso exista.
  const customEnvName = String(
    channelConfig.token_env
    || channelConfig.bot_token_env
    || ''
  ).trim();

  const customToken = customEnvName
    ? env(customEnvName)
    : '';

  return customToken || tenantToken || '';
}

async function sendTelegramMessage(context = {}, payload = {}) {
  const token = telegramTokenFor(context);

  if (!payload?.chat_id || !payload?.text) {
    return { ok: true, skipped: true, reason: 'telegram_payload_empty' };
  }

  if (!token) {
    throw new Error('token nao configurado para tenant=' + tenantSlug + ' channel=telegram');
  }

  return await httpJson(
    'POST',
    'https://api.telegram.org/bot' + token + '/sendMessage',
    { 'Content-Type': 'application/json' },
    {
      chat_id: payload.chat_id,
      text: payload.text,
      disable_web_page_preview: payload.disable_web_page_preview ?? true,
    }
  );
}

async function sendTelegramFallbackMessage(text) {
  const token = env('TELEGRAM_BOT_TOKEN_' + tenantEnvSuffix(tenantSlug));
  if (!token || !chatId || !text) return null;

  return await httpJson(
    'POST',
    'https://api.telegram.org/bot' + token + '/sendMessage',
    { 'Content-Type': 'application/json' },
    {
      chat_id: chatId,
      text,
      disable_web_page_preview: true,
    }
  );
}

function detectTelegramMedia(msg = {}) {
  if (msg.voice?.file_id) {
    return {
      kind: 'voice',
      category: 'audio',
      fileId: msg.voice.file_id,
      fileSize: Number(msg.voice.file_size || 0),
      duration: Number(msg.voice.duration || 0),
      mimeType: msg.voice.mime_type || 'audio/ogg',
      supported: true,
    };
  }

  if (msg.audio?.file_id) {
    return {
      kind: 'audio',
      category: 'audio',
      fileId: msg.audio.file_id,
      fileSize: Number(msg.audio.file_size || 0),
      duration: Number(msg.audio.duration || 0),
      mimeType: msg.audio.mime_type || 'audio/mpeg',
      fileName: msg.audio.file_name || '',
      supported: true,
    };
  }

  if (Array.isArray(msg.photo) && msg.photo.length) {
    const largest = msg.photo[msg.photo.length - 1];

    return {
      kind: 'photo',
      category: 'image',
      fileId: largest.file_id,
      fileSize: Number(largest.file_size || 0),
      width: Number(largest.width || 0),
      height: Number(largest.height || 0),
      mimeType: 'image/jpeg',
      supported: true,
    };
  }

  if (msg.sticker?.file_id) {
    const isAnimated = Boolean(msg.sticker.is_animated);
    const isVideo = Boolean(msg.sticker.is_video);

    return {
      kind: 'sticker',
      category: 'image',
      fileId: msg.sticker.file_id,
      fileSize: Number(msg.sticker.file_size || 0),
      mimeType: isVideo
        ? 'video/webm'
        : isAnimated
          ? 'application/x-tgsticker'
          : 'image/webp',
      supported: !isAnimated && !isVideo,
      unsupportedReason: isAnimated
        ? 'animated_sticker_not_supported'
        : isVideo
          ? 'video_sticker_not_supported'
          : '',
    };
  }

  if (msg.document?.file_id) {
    const mimeType = String(
      msg.document.mime_type || ''
    ).toLowerCase();

    if (mimeType.startsWith('image/')) {
      return {
        kind: 'image_document',
        category: 'image',
        fileId: msg.document.file_id,
        fileSize: Number(msg.document.file_size || 0),
        mimeType,
        fileName: msg.document.file_name || '',
        supported: true,
      };
    }

    if (mimeType.startsWith('audio/')) {
      return {
        kind: 'audio_document',
        category: 'audio',
        fileId: msg.document.file_id,
        fileSize: Number(msg.document.file_size || 0),
        mimeType,
        fileName: msg.document.file_name || '',
        supported: true,
      };
    }

    return {
      kind: 'document',
      category: 'document',
      fileId: msg.document.file_id,
      fileSize: Number(msg.document.file_size || 0),
      mimeType: mimeType || 'application/octet-stream',
      fileName: msg.document.file_name || '',
      supported: false,
      unsupportedReason: 'document_type_not_supported',
    };
  }

  if (msg.video?.file_id || msg.video_note?.file_id) {
    const source = msg.video || msg.video_note;

    return {
      kind: msg.video_note ? 'video_note' : 'video',
      category: 'video',
      fileId: source.file_id,
      fileSize: Number(source.file_size || 0),
      duration: Number(source.duration || 0),
      mimeType: source.mime_type || 'video/mp4',
      supported: false,
      unsupportedReason: 'video_not_enabled_yet',
    };
  }

  return null;
}

function mediaFallbackText(media = {}, reason = '') {
  if (media.category === 'audio') {
    if (reason === 'media_too_large') {
      return 'Recebi seu áudio ✨ Ele ficou grande demais para eu processar por aqui. Pode me enviar um áudio menor ou escrever a mensagem?';
    }

    if (reason === 'audio_too_long') {
      return 'Recebi seu áudio ✨ Para eu conseguir processar direitinho, pode me mandar um áudio mais curto ou escrever a mensagem?';
    }

    if (reason === 'media_audio_unintelligible') {
      return 'Recebi seu áudio ✨ Não consegui entender a fala com segurança. Pode enviar novamente ou escrever a mensagem?';
    }

    return 'Recebi seu áudio ✨ Tive uma dificuldade para processá-lo agora. Se puder, envie novamente ou escreva a mensagem.';
  }

  if (media.category === 'image') {
    if (reason === 'media_too_large') {
      return 'Recebi sua imagem ✨ Ela ficou grande demais para eu analisar por aqui. Se puder, envie uma versão menor ou me explique em texto o que deseja saber.';
    }

    if (media.kind === 'sticker') {
      return 'Recebi sua figurinha 😄 Se quiser, me conta em texto como posso te ajudar.';
    }

    return 'Recebi sua imagem ✨ Tive uma dificuldade para analisá-la agora. Se puder, envie novamente ou me diga em texto o que gostaria de saber.';
  }

  if (media.category === 'video') {
    return 'Recebi seu vídeo ✨ Por enquanto consigo entender mensagens de texto, áudios e imagens. Se puder, envie uma foto do que quer mostrar ou me explique em texto.';
  }

  return 'Recebi seu arquivo ✨ Por enquanto consigo entender mensagens de texto, áudios e imagens.';
}

async function downloadTelegramMedia(context, media) {
  const token = telegramTokenFor(context);

  if (!token) {
    throw mediaError(
      'TELEGRAM_BOT_TOKEN_' + tenantEnvSuffix(tenantSlug) + ' nao configurado',
      'telegram_media_token_missing'
    );
  }

  const configuredMaxBytes = Number(
    env('TELEGRAM_MEDIA_MAX_BYTES', 10485760)
  );

  const maxBytes = Math.max(
    1048576,
    Math.min(
      Number.isFinite(configuredMaxBytes)
        ? configuredMaxBytes
        : 10485760,
      15728640
    )
  );

  const configuredMaxAudioSeconds = Number(
    env('TELEGRAM_MEDIA_MAX_AUDIO_SECONDS', 300)
  );

  const maxAudioSeconds = Math.max(
    30,
    Math.min(
      Number.isFinite(configuredMaxAudioSeconds)
        ? configuredMaxAudioSeconds
        : 300,
      900
    )
  );

  if (media.fileSize && media.fileSize > maxBytes) {
    throw mediaError(
      'Arquivo maior que o limite interno',
      'media_too_large'
    );
  }

  if (
    media.category === 'audio'
    && media.duration
    && media.duration > maxAudioSeconds
  ) {
    throw mediaError(
      'Audio maior que o limite interno de duracao',
      'audio_too_long'
    );
  }

  let fileInfo;

  try {
    fileInfo = await httpJson(
      'GET',
      'https://api.telegram.org/bot'
        + token
        + '/getFile?file_id='
        + encodeURIComponent(media.fileId)
    );
  } catch (error) {
    throw mediaError(
      'Falha ao consultar getFile no Telegram: '
        + (error.message || String(error)),
      'telegram_get_file_failed'
    );
  }

  const filePath = fileInfo?.result?.file_path;

  if (!fileInfo?.ok || !filePath) {
    throw mediaError(
      fileInfo?.description
        || 'Telegram nao retornou file_path',
      'telegram_file_path_missing'
    );
  }

  const fileUrl = 'https://api.telegram.org/file/bot'
    + token
    + '/'
    + filePath;

  let downloaded;

  try {
    downloaded = await helpers.httpRequest({
      method: 'GET',
      url: fileUrl,
      encoding: 'arraybuffer',
      timeout: 45000,
    });
  } catch (error) {
    throw mediaError(
      'Falha ao baixar a midia do Telegram: '
        + (error.message || String(error)),
      'telegram_media_download_failed'
    );
  }

  const buffer = Buffer.isBuffer(downloaded)
    ? downloaded
    : Buffer.from(downloaded || []);

  if (!buffer.length) {
    throw mediaError(
      'Midia baixada sem conteudo',
      'telegram_media_empty'
    );
  }

  if (buffer.length > maxBytes) {
    throw mediaError(
      'Arquivo baixado excede o limite interno',
      'media_too_large'
    );
  }

  return {
    base64: buffer.toString('base64'),
    bytes: buffer.length,
    mimeType: media.mimeType || 'application/octet-stream',
  };
}

async function analyzeTelegramMedia(context, media) {
  const enabled = String(
    env('TELEGRAM_MEDIA_ENABLED', 'true')
  ).toLowerCase() === 'true';

  if (!enabled) {
    throw mediaError(
      'Processamento multimodal desabilitado',
      'media_processing_disabled'
    );
  }

  if (!media.supported) {
    throw mediaError(
      'Tipo de midia ainda nao suportado',
      media.unsupportedReason || 'media_type_not_supported'
    );
  }

  const gate = usageGate(context);

  if (!gate.enabled) {
    throw mediaError(
      'Gemini desabilitado',
      'media_gemini_disabled'
    );
  }

  if (!gate.hasKey) {
    throw mediaError(
      'GEMINI_API_KEY ausente',
      'media_gemini_key_missing'
    );
  }

  if (gate.forceMock) {
    throw mediaError(
      'IA do tenant desabilitada',
      'media_tenant_ai_disabled'
    );
  }

  if (
    gate.hasDailyLimit
    && gate.usedToday >= gate.dailyLimit
  ) {
    throw mediaError(
      'Limite diario interno atingido',
      'media_daily_limit_reached'
    );
  }

  const downloaded = await downloadTelegramMedia(
    context,
    media
  );

  const settings = settingsFor(context);
  const agent = context.agent || {};
  const model = settings.ai_model
    || agent.model
    || env('GEMINI_MODEL', 'gemini-2.5-flash-lite');

  const instruction = media.category === 'audio'
    ? `Transcreva fielmente a fala deste áudio em português do Brasil.
Retorne SOMENTE a transcrição.
Não responda à pessoa.
Não acrescente introdução.
Não invente palavras.
Se não houver fala inteligível, retorne exatamente [SEM_FALA_INTELIGIVEL].`
    : `Analise esta imagem como contexto para uma conversa de atendimento.
Descreva somente fatos visualmente observáveis e texto legível relevante.
Se for algo cotidiano e não relacionado à empresa, como um animal, objeto ou ambiente, descreva isso normalmente.
Não identifique pessoas.
Não infira gênero, idade, raça, etnia ou identidade de pessoas.
Não faça diagnóstico médico ou dermatológico.
Não invente contexto.
Retorne uma descrição objetiva em português do Brasil com no máximo 700 caracteres.`;

  const body = await httpJson(
    'POST',
    'https://generativelanguage.googleapis.com/v1beta/models/'
      + model
      + ':generateContent',
    {
      'Content-Type': 'application/json',
      'x-goog-api-key': env('GEMINI_API_KEY'),
    },
    {
      contents: [{
        role: 'user',
        parts: [
          {
            inlineData: {
              mimeType: downloaded.mimeType,
              data: downloaded.base64,
            },
          },
          { text: instruction },
        ],
      }],
      generationConfig: {
        temperature: 0.1,
        topP: 0.8,
        maxOutputTokens: media.category === 'audio'
          ? 1400
          : 500,
        candidateCount: 1,
      },
    },
  );

  const candidate = body?.candidates?.[0] || {};

  const extractedText = candidate?.content?.parts
    ?.map((part) => part.text || '')
    .join('')
    .trim() || '';

  if (!extractedText) {
    throw mediaError(
      'Gemini nao retornou texto para a midia',
      'media_gemini_empty'
    );
  }

  if (
    media.category === 'audio'
    && extractedText.includes('[SEM_FALA_INTELIGIVEL]')
  ) {
    throw mediaError(
      'Audio sem fala inteligivel',
      'media_audio_unintelligible'
    );
  }

  // A chamada multimodal também conta como uso da IA.
  markUsage();

  return {
    text: extractedText,
    model,
    bytes: downloaded.bytes,
    mimeType: downloaded.mimeType,
    finishReason: String(candidate.finishReason || ''),
    usage: body?.usageMetadata || {},
  };
}

function supabaseHeaders(prefer) {
  const serviceKey = env('SUPABASE_SERVICE_ROLE_KEY');
  return {
    apikey: serviceKey,
    Authorization: 'Bearer ' + serviceKey,
    'Content-Type': 'application/json',
    ...(prefer ? { Prefer: prefer } : {}),
  };
}

function supabaseUrl(pathname) {
  const base = env('SUPABASE_URL').replace(/\/$/, '');
  if (!base) throw new Error('SUPABASE_URL nao configurada no n8n');
  if (!env('SUPABASE_SERVICE_ROLE_KEY')) throw new Error('SUPABASE_SERVICE_ROLE_KEY nao configurada no n8n');
  return base + pathname;
}

async function supabaseGet(pathname) {
  return httpJson('GET', supabaseUrl(pathname), supabaseHeaders());
}

async function supabasePost(pathname, payload, prefer = 'return=representation') {
  return httpJson('POST', supabaseUrl(pathname), supabaseHeaders(prefer), payload);
}

async function supabasePatch(pathname, payload, prefer = 'return=representation') {
  return httpJson('PATCH', supabaseUrl(pathname), supabaseHeaders(prefer), payload);
}

function encodeFilter(value) {
  return encodeURIComponent(String(value));
}

async function loadTenantContext() {
  const tenants = await supabaseGet('/rest/v1/tenants?select=*&slug=eq.' + encodeFilter(tenantSlug) + '&limit=1');
  const tenant = tenants?.[0];
  if (!tenant || tenant.status !== 'active' || tenant.id !== inputJson.tenant_id) throw new Error('Invalid tenant');
  const settingRows = await supabaseGet('/rest/v1/tenant_settings?select=*&tenant_id=eq.' + tenant.id);
  if (settingRows.length !== 1) throw new Error('Invalid tenant settings');
  if (settingRows[0].settings?.whatsapp_processing_mode !== 'conversation_core_v1') throw new Error('Core not enabled for tenant');
  const agentRows = settingRows[0].settings?.grounding_mode === 'canonical_v2' ? []
    : await supabaseGet('/rest/v1/ai_agents?select=*&tenant_id=eq.' + tenant.id + '&provider=eq.gemini&order=created_at.asc&limit=1');
  const channelRows = await supabaseGet('/rest/v1/channels?select=*&tenant_id=eq.' + tenant.id
    + '&type=eq.whatsapp&status=eq.active&external_id=eq.' + encodeFilter(inputJson.instance) + '&limit=1');
  if (!channelRows.length) throw new Error('Instance does not belong to tenant');
  // core-extension-business-context-v1
  const businessContext = inputJson.noria_business_context;
  if (businessContext !== undefined && (!businessContext || typeof businessContext !== 'object'
    || businessContext.contract !== 'noria_business_result_v1'
    || businessContext.tenant_slug !== tenantSlug)) throw new Error('NORIA_BUSINESS_CONTEXT_INVALID');
  return { tenant, settings: settingRows[0], agent: agentRows[0] || {}, channel: channelRows[0],
    client_policy: tenantBusinessRules, noria_client_policy: tenantBusinessRules,
    noria_business_context: businessContext || null, business_context: businessContext || null };
}

async function loadRecentHistory(context = {}) {
  const base = '/rest/v1/channel_events?select=*'
    + '&tenant_slug=eq.' + encodeFilter(tenantSlug) + '&channel_type=eq.whatsapp'
    + '&external_conversation_id=eq.' + encodeFilter(chatId);
  const boundary = await supabaseGet(base
    + '&or=(service.eq.conversation_closed,ai_provider.eq.conversation_closed,ai_provider.eq.conversation_reset)'
    + '&order=created_at.desc,id.desc&limit=1');
  const grounded = settingsFor(context).grounding_mode === 'canonical_v2';
  const rows = await supabaseGet(base + '&or=(ai_provider.is.null,ai_provider.neq.buffer)'
    + (boundary[0] ? '&created_at=gt.' + encodeFilter(boundary[0].created_at) : '')
    + '&order=created_at.desc,id.desc&limit=' + (grounded ? 251 : 50));
  if (!Array.isArray(rows)) throw new Error('Conversation history unavailable');
  turn.boundary_created_at = boundary[0]?.created_at || null;
  // The queue claim and the history lookup must describe the same attendance.
  turn.history_boundary_changed = !!turn.boundary_id && turn.boundary_id !== (boundary[0]?.id || 'initial');
  turn.history_overflow = grounded && rows.length > 250;
  return rows.reverse();
}

async function alreadyProcessedExternalMessage(externalMessageId) {
  if (!externalMessageId) return false;

  try {
    const path = '/rest/v1/channel_events?select=external_message_id'
      + '&tenant_slug=eq.' + encodeFilter(tenantSlug)
      + '&channel_type=eq.whatsapp'
      + '&external_conversation_id=eq.' + encodeFilter(String(chatId))
      + '&external_message_id=eq.' + encodeFilter(String(externalMessageId))
      + '&limit=1';

    const rows = await supabaseGet(path);
    return Array.isArray(rows) && rows.length > 0;
  } catch (error) {
    // Deduplicação nunca pode derrubar o atendimento.
    return false;
  }
}

function eventTime(event) {
  const value = Date.parse(event?.created_at || '');
  return Number.isFinite(value) ? value : 0;
}

function isHumanOutbound(event) {
  if (!event || event.direction !== 'outbound') return false;
  const senderType = normalizeText(event.sender_type);
  const sentBy = normalizeText(event.sent_by_user);
  if (['human', 'agent', 'operator', 'atendente'].includes(senderType)) return true;
  return Boolean(event.handoff && sentBy && !sentBy.includes('assistente') && !sentBy.includes('bot') && !sentBy.includes('ia'));
}

function isConversationClosedEvent(event) {
  const stage = normalizeText(event?.stage);
  const service = normalizeText(event?.service);
  const provider = normalizeText(event?.ai_provider);
  const message = normalizeText(event?.message_text);

  return stage === 'finalizado'
    || stage === 'finalizada'
    || stage === 'encerrado'
    || stage === 'encerrada'
    || stage === 'fechado'
    || stage === 'fechada'
    || service === 'conversation_closed'
    || provider === 'conversation_closed'
    || message === 'atendimento encerrado pela interface';
}

function historyAfterControlBoundary(history = []) {
  let boundaryIndex = -1;
  history.forEach((event, index) => {
    const stage = normalizeText(event.stage);
    const provider = normalizeText(event.ai_provider);
    if (isConversationClosedEvent(event) || stage === 'reset' || provider === 'conversation_reset') {
      boundaryIndex = index;
    }
  });
  return boundaryIndex >= 0 ? history.slice(boundaryIndex + 1) : history;
}

function conversationControl(history = []) {
  const activeHistory = historyAfterControlBoundary(history);
  const lastResume = activeHistory.findLastIndex(event => event.service === 'resume_ai' || event.ai_provider === 'resume_ai');
  const afterResume = activeHistory.slice(lastResume + 1);
  const event = [...afterResume].reverse().find(item => item.handoff === true || isHumanOutbound(item));
  return { activeHistory, lockedByHuman: !!event, lockEvent: event || null, lockSource: event ? 'human_control' : null };
}

async function loadAppointments(tenantId, includePrevious = false) {
  const rows = await supabaseGet('/rest/v1/appointments?select=*&tenant_id=eq.' + encodeFilter(tenantId)
    + '&channel_type=eq.whatsapp&external_conversation_id=eq.' + encodeFilter(chatId)
    + (!includePrevious ? '&status=not.in.(cancelled,canceled,completed,done,no_show)&starts_at=gt.' + encodeFilter(new Date().toISOString())
      + (turn?.boundary_created_at ? '&created_at=gt.' + encodeFilter(turn.boundary_created_at) : '') : '')
    + '&order=created_at.desc&limit=31');
  if (!Array.isArray(rows)) throw new Error('Appointments unavailable');
  const scoped = includePrevious ? rows : rows.filter(row => {
    if (['cancelled','canceled','completed','done','no_show'].includes(row.status) || Date.parse(row.starts_at) <= Date.now()) return false;
    const session = row.metadata?.conversation_session_id;
    if (session) return session === (turn?.boundary_id || 'initial');
    return !turn?.boundary_created_at || Date.parse(row.created_at) > Date.parse(turn.boundary_created_at);
  });
  return { rows: scoped, error: '', overflow: rows.length > 30 };
}

function appointmentState(rows = [], now = Date.now()) {
  const cancelled = new Set(['cancelled', 'canceled', 'cancelado', 'cancelada', 'deleted']);
  const active = new Set(['scheduled', 'confirmed', 'booked', 'reserved', 'rescheduled', 'pending_payment', 'payment_reported', 'agendado', 'agendada', 'confirmado', 'confirmada']);
  const normalizedRows = rows
    .map((row) => ({ ...row, startsAtMs: Date.parse(row.starts_at || ''), statusKey: normalizeText(row.status || 'scheduled') }))
    .filter((row) => !cancelled.has(row.statusKey) && Number.isFinite(row.startsAtMs));
  const futureConfirmed = normalizedRows
    .filter((row) => row.startsAtMs > now && active.has(row.statusKey))
    .sort((left, right) => left.startsAtMs - right.startsAtMs)[0] || null;
  const passed = normalizedRows
    .filter((row) => row.startsAtMs <= now)
    .sort((left, right) => right.startsAtMs - left.startsAtMs)[0] || null;

  return {
    rows: normalizedRows,
    futureConfirmed,
    passed,
    hasConfirmed: Boolean(futureConfirmed),
    hasPassed: Boolean(passed),
  };
}

function parseAppointmentCreationTag(text) {
  const source = String(text || '').replace(/\[A[C\u00c7][A\u00c3]O\s*:/gi, '[ACAO:');
  const match = source.match(new RegExp(String.raw`\[(?:A??O|ACAO)\s*:\s*(?:CRIAR_AGENDAMENTO|AGENDAMENTO_CONFIRMADO)([^\]]*)\]`, 'i'));
  if (!match) return null;

  const details = {};
  const tail = String(match[1] || '').replace(/^\s*[|:;,-]\s*/, '');
  for (const part of tail.split('|')) {
    const [rawKey, ...rawValueParts] = part.split('=');
    const key = normalizeText(rawKey).replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    const value = rawValueParts.join('=').trim();
    if (key && value) details[key] = value;
  }

  return {
    customerName: details.nome || details.cliente || details.customer_name || '',
    service: details.servico || details.service || '',
    date: details.data || details.date || '',
    time: details.hora || details.horario || details.time || '',
    durationMinutes: Number(details.duracao || details.duration || 60),
    status: normalizeText(details.status || details.situacao || details.estado || ''),
    raw: match[0],
  };
}

function isoDateInTenantTimezone(offsetDays = 0, context = {}) {
  const base = new Date(Date.now() + Number(offsetDays || 0) * 24 * 60 * 60 * 1000);
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: tenantTimeZone(context),
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(base);
}

function parseAppointmentStartAt(dateValue, timeValue, context = {}) {
  const rawDateText = String(dateValue || '').trim();
  const dateText = normalizeText(rawDateText);
  const timeMatch = normalizeText(timeValue).match(/(\d{1,2})(?::|h)?(\d{2})?/);
  if (!dateText || !timeMatch) return null;
  let normalizedDate = rawDateText;
  if (['hoje','hj'].includes(dateText)) normalizedDate = isoDateInTenantTimezone(0, context);
  else if (dateText === 'amanha') normalizedDate = isoDateInTenantTimezone(1, context);
  else if (dateText.includes('depois de amanha')) normalizedDate = isoDateInTenantTimezone(2, context);
  const iso = normalizedDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const br = normalizedDate.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  let year, month, day;
  if (iso) [year,month,day] = iso.slice(1).map(Number);
  else if (br) {
    day=Number(br[1]);month=Number(br[2]);
    year=br[3]?Number(br[3]):Number(new Intl.DateTimeFormat('en-CA',{timeZone:tenantTimeZone(context),year:'numeric'}).format(new Date()));
    if (year < 100) year += 2000;
  } else return null;
  const hour=Number(timeMatch[1]), minute=Number(timeMatch[2]||0);
  if (![year,month,day,hour,minute].every(Number.isFinite)
      || month<1||month>12||day<1||day>31||hour<0||hour>23||minute<0||minute>59) return null;
  const zone=tenantTimeZone(context);
  const target=Date.UTC(year,month-1,day,hour,minute,0);
  let candidate=target;
  const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
  for(let i=0;i<3;i++){
    const parts=Object.fromEntries(formatter.formatToParts(new Date(candidate)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));
    const rendered=Date.UTC(Number(parts.year),Number(parts.month)-1,Number(parts.day),Number(parts.hour),Number(parts.minute),Number(parts.second));
    candidate += target-rendered;
  }
  const check=Object.fromEntries(formatter.formatToParts(new Date(candidate)).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
  if (check.year!==year||check.month!==month||check.day!==day||check.hour!==hour||check.minute!==minute) return null;
  return new Date(candidate).toISOString();
}

async function createAppointmentFromTag(context, tagData, contactName) {
  const settings = settingsFor(context);
  if (!tagData) return { created: false, reason: 'no_appointment_tag' };

  const startsAt = parseAppointmentStartAt(tagData.date, tagData.time, context);
  if (!startsAt) return { created: false, reason: 'invalid_appointment_datetime', tag: tagData };

  const configuredDuration = Number(settings.appointment_duration_minutes || 60);
  const duration = Number.isFinite(tagData.durationMinutes) && tagData.durationMinutes > 0 ? Math.min(Math.max(tagData.durationMinutes, 15), 480) : Math.min(Math.max(configuredDuration, 15), 480);
  const endsAt = new Date(new Date(startsAt).getTime() + duration * 60 * 1000).toISOString();
  const safeContactName = tagData.customerName || contactName || 'Contato';
  const safeService = tagData.service || 'Atendimento';
  const title = safeService + ' - ' + safeContactName;
  const configuredStatus = normalizeText(settings.default_ai_appointment_status || 'pending_payment');
  const paymentConfig = paymentSignalSettingsFor(context);
  const paymentRequired = paymentConfig.enabled || configuredStatus === 'pending_payment';
  const requestedStatus = normalizeText(tagData.status || configuredStatus || 'pending_payment');
  const allowedStatuses = new Set(['pending_payment', 'scheduled', 'confirmed', 'reserved']);
  const appointmentStatus = paymentRequired
    ? 'pending_payment'
    : (allowedStatuses.has(requestedStatus) ? requestedStatus : 'pending_payment');

  const existingPath = '/rest/v1/appointments?select=id,title,starts_at,status' + '&tenant_id=eq.' + encodeFilter(context.tenant.id) + '&channel_type=eq.whatsapp' + '&external_conversation_id=eq.' + encodeFilter(String(chatId)) + '&starts_at=eq.' + encodeFilter(startsAt) + '&limit=1';
  const existing = await supabaseGet(existingPath).catch(() => []);
  if (Array.isArray(existing) && existing.length) return { created: false, duplicate: true, appointment: existing[0], startsAt, endsAt, tag: tagData };

  const payload = {
    tenant_id: context.tenant.id,
    title,
    starts_at: startsAt,
    ends_at: endsAt,
    status: appointmentStatus,
    contact_name: safeContactName,
    channel_type: 'whatsapp',
    external_conversation_id: String(chatId),
    notes: appointmentStatus === 'pending_payment'
      ? 'Pre-agendamento criado pela IA. Aguardando pagamento do sinal.'
      : 'Criado automaticamente pela IA a partir da conversa.',
    metadata: { source: 'ai_conversation', tenant_slug: tenantSlug, service: safeService, customer_name: safeContactName, requested_date: tagData.date, requested_time: tagData.time, duration_minutes: duration, whatsapp_chat_id: String(chatId), whatsapp_message_id: message?.message_id ? String(message.message_id) : null, payment_status: appointmentStatus === 'pending_payment' ? 'awaiting_signal' : 'not_required' },
  };

  const saved = await supabasePost('/rest/v1/appointments', payload, 'return=representation');
  const row = Array.isArray(saved) ? saved[0] : saved;
  return { created: true, appointment: row, startsAt, endsAt, status: appointmentStatus, tag: tagData };
}

async function markLatestAppointmentPaymentReported(context) {
  const rows = (await loadAppointments(context.tenant.id)).rows;
  const candidates = rows.filter(row => ['pending_payment','reserved','payment_requested'].includes(row.status))
    .sort((a,b) => Date.parse(b.created_at) - Date.parse(a.created_at));
  if (candidates.length > 1) return { updated: false, reason: 'ambiguous_payment_appointment' };
  const target = candidates[0];
  if (!target) return { updated: false, reason: 'appointment_not_found' };
  const payload = { status: 'payment_reported', metadata: { ...target.metadata,
    payment_status: 'reported_by_customer', payment_reported_at: new Date().toISOString() }, updated_at: new Date().toISOString() };
  const saved = await supabasePatch('/rest/v1/appointments?id=eq.' + encodeFilter(target.id)
    + '&tenant_id=eq.' + encodeFilter(context.tenant.id) + '&status=eq.' + encodeFilter(target.status), payload);
  if (saved.length !== 1) throw new Error('Appointment changed during payment report');
  return { updated: true, appointment: saved[0], previous_status: target.status };
}

function appointmentDateLabel(appointment) {
  if (!appointment?.starts_at) return 'data nao informada';
  return new Intl.DateTimeFormat('pt-BR', {
    dateStyle: 'short',
    timeStyle: 'short',
    timeZone: env('APP_TIMEZONE', 'America/Sao_Paulo'),
  }).format(new Date(appointment.starts_at));
}

function asksAppointmentStatus() {
  return hasAny([
    'meu agendamento',
    'minha agenda',
    'agendamento confirmado',
    'consulta marcada',
    'horario marcado',
    'esta confirmado',
    'ja confirmei',
    'ja agendei',
    'quando e meu horario',
    'que dia e meu horario',
    'passou meu agendamento',
  ]);
}

function appointmentResponse(state, classification, settings) {
  if (state.futureConfirmed && (classification.stage === 'Agendamento' || asksAppointmentStatus())) {
    const title = state.futureConfirmed.title || 'seu atendimento';
    return `Encontrei ${title} confirmado para ${appointmentDateLabel(state.futureConfirmed)}. Se precisar alterar ou cancelar, me avise para eu encaminhar a equipe.`;
  }
  if (state.passed && (classification.stage === 'Agendamento' || asksAppointmentStatus())) {
    const title = state.passed.title || 'seu atendimento';
    return `O agendamento de ${title}, previsto para ${appointmentDateLabel(state.passed)}, ja passou. Quer que eu encaminhe a equipe para remarcar? [HUMANO_SOLICITADO]`;
  }
  if (asksAppointmentStatus() && !state.rows.length) {
    return `${settings.no_appointment_message || 'Nao encontrei um agendamento confirmado para esta conversa.'} Se quiser, posso encaminhar a equipe para verificar ou marcar um novo horario.`;
  }
  return '';
}

function wantsFullCatalogRequest() {
  const value = normalizeText(rawText);

  const triggers = [
    'todos os servicos',
