  if(kindIds.some(id=>!allowed.has(String(id)))||kind!=='unknown'&&!kindIds.length)throw Error('UNSCOPED_ENTRY_VEHICLE_KIND');
  const kindMemory=status==='none'&&(!previous.trade_in_status||previous.trade_in_status==='none')
