  if(status==='none'&&previous.trade_in_status&&previous.trade_in_status!=='none'){
    const old=(previous.evidence_ids||[]).map(String).filter(id=>allowed.has(id));
    return old.length?{trade_in_status:previous.trade_in_status,evidence_ids:old,...kindMemory,...purposeMemory,...catalogMemory}:{trade_in_status:'none',evidence_ids:[],...kindMemory,...purposeMemory,...catalogMemory};
