  return {trade_in_status:status,evidence_ids:ids,...kindMemory,...purposeMemory,...catalogMemory};
}
function renderCatalogDraft(draft,items=[]){
  const c=draft?.catalog;
  if(!c||typeof c.intro!=='string'||typeof c.closing!=='string'||typeof c.include_prices!=='boolean'
    ||!Array.isArray(c.item_ids)||c.item_ids.length!==items.length
    ||c.item_ids.some((id,i)=>id!==items[i].id)||new Set(c.item_ids).size!==items.length
    ||c.intro.length>700||c.closing.length>700)throw Error('INVALID_CATALOG_LAYOUT');
  const rows=items.map((item,i)=>{
    if(typeof item.label!=='string'||!item.label.trim()||/[\r\n]/.test(item.label))throw Error('INVALID_CATALOG_LABEL');
    const price=c.include_prices&&Number.isSafeInteger(item.price_cents)&&item.price_cents>=0
      ?' — R$ '+(item.price_cents/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}):'';
    return (i+1)+') '+item.label+price;
  });
  return {...draft,reply:[c.intro.trim(),rows.join('\n'),c.closing.trim()].filter(Boolean).join('\n\n')};
}
function validatePlan(plan,sessionIds=[],previousMemory={}){
  if(!plan||typeof plan!=='object')throw Error('INVALID_DIALOGUE_PLAN');
  if(!Array.isArray(plan.requests)||plan.requests.length>8)throw Error('INVALID_DIALOGUE_REQUESTS');
  for(const r of plan.requests){if(typeof r.topic!=='string'||!r.topic.trim())throw Error('INVALID_DIALOGUE_REQUEST');}
  const requests=plan.requests.map((r,i)=>({...r,id:'request_'+(i+1)}));
  const requirements=['none','customer_name','deposit','documents','purchase_product','sell_model','buy_model','vehicle_photo','vehicle_description','trade_in_confirmation','buy_and_sell_models'];
  if(!requirements.includes(plan.next_requirement))throw Error('INVALID_DIALOGUE_REQUIREMENT');
  if(!['none','human_requested','appraisal_review'].includes(plan.handoff_reason))throw Error('INVALID_DIALOGUE_HANDOFF');
  if(plan.handoff_reason==='human_requested'&&plan.human_requested!==true)throw Error('UNREQUESTED_DIALOGUE_HANDOFF');
  const memory=mergeMemory(previousMemory,plan.memory||{},sessionIds);
  if(plan.handoff_reason==='appraisal_review'&&memory.trade_in_status!=='offered')throw Error('POLICY_IS_NOT_OFFER');
  return {...plan,requests,memory};
}
function validateDraft(draft,plan,facts=[]){
  const issues=[];
  if(!draft||typeof draft.reply!=='string'||!draft.reply.trim()||draft.reply.length>3500)return ['INVALID_REPLY'];
  const answered=new Set(draft.answered_request_ids||[]);
  for(const r of plan.requests||[])if(!answered.has(r.id))issues.push('UNANSWERED_REQUEST:'+r.id);
  const ledger=new Map(facts.map(f=>[f.id,f.value]));
  if(!Array.isArray(draft.claims))issues.push('MISSING_CLAIMS');
  for(const claim of draft.claims||[]){
    if(!ledger.has(claim.fact_id)||JSON.stringify(ledger.get(claim.fact_id))!==JSON.stringify(claim.value))issues.push('UNSUPPORTED_FACT:'+claim.fact_id);
  }
  const permittedMoney=new Set(facts.filter(f=>/(?:price_cents|deposit_cents)$/.test(f.id)).map(f=>Number(f.value)).filter(Number.isSafeInteger));
  for(const match of draft.reply.matchAll(/R\$\s*(\d+(?:\.\d{3})*(?:,\d{1,2})?)/gi)){
    const cents=Math.round(Number(match[1].replace(/\./g,'').replace(',','.'))*100);
    if(!permittedMoney.has(cents))issues.push('UNSUPPORTED_AMOUNT:'+cents);
  }
  return issues;
}
async function compose({plan,facts=[],execution={},generate,audit}){
  let issues=[],attempts=[],previousDraft=null;
  for(let i=0;i<1;i++){
    try{
      const draft=await generate({issues,attempt:i+1,previous_draft:previousDraft});
      previousDraft=draft;
      issues=validateDraft(draft,plan,facts);
      // Claims, request coverage and monetary values are validated locally.
      // Avoid a second Gemini call that audits the response it just produced.
      attempts.push({attempt:i+1,issues:[...issues]});
      if(!issues.length)return {status:i?'repaired':'accepted',reply:draft.reply,attempts};
    }catch(error){
      issues=[String(error.message||'').startsWith('INVALID_CATALOG_')?String(error.message):'DIALOGUE_PROVIDER_FAILURE'];
      const diagnostic=salesSafeFailureDiagnostics(error,'dialogue_compose');
      attempts.push({attempt:i+1,issues,diagnostic});
      // Auth/model/schema failures cannot be repaired by asking the provider three times.
      if (['authentication','model_unavailable','invalid_request_or_schema','configured_usage_limit','rate_limit'].includes(diagnostic.category)) break;
    }
  }
  return {status:'needs_human_review',reply:null,attempts};
}
function validateReview(review,facts=[]){
  const issues=[];
  if(review?.ok!==true||!Array.isArray(review.issues)||review.issues.length)issues.push(...(review?.issues?.length?review.issues:['UNVERIFIED_RESPONSE']));
  if(!Array.isArray(review?.assertions))issues.push('MISSING_AUDIT_ASSERTIONS');
  const ledger=new Map(facts.map(f=>[f.id,f.value]));
  for(const a of review?.assertions||[]){
    if(!ledger.has(a.fact_id)||JSON.stringify(ledger.get(a.fact_id))!==JSON.stringify(a.value))issues.push('UNSUPPORTED_ASSERTION:'+a.fact_id);
  }
  return issues;
}
function responseContract(plan={},state={},execution={}){
  const status=plan.memory?.trade_in_status||state.dialogue_memory?.trade_in_status||'none';
  const selling=['sell','buy_and_sell'].includes(state.transaction_mode);
  const purpose=plan.customer_vehicle_purpose||(plan.buy_only_current?'none':plan.memory?.customer_vehicle_purpose||state.dialogue_memory?.customer_vehicle_purpose||(status==='offered'?'entry':selling?'independent_sale':'none'));
  const entry=['policy_discussed','offered'].includes(status)&&!plan.buy_only_current&&purpose!=='independent_sale';
  return {customer_vehicle_purpose:purpose,vehicle_entry_discussion_allowed:entry,
    customer_vehicle_details_allowed:!execution.assigned&&(purpose==='independent_sale'||entry),
