  if(o.mechanical==='confirmed'&&g.mechanical_report_verified!==true)issues.push('UNVERIFIED_MECHANICAL_ASSERTION');
  if(o.credit==='approved'||o.credit==='guaranteed_denial')issues.push('UNVERIFIED_CREDIT_ASSERTION');
  if(['confirmed','promised'].includes(o.assignment)&&g.assigned!==true)issues.push('UNCONFIRMED_ASSIGNMENT_ASSERTION');
  if(o.registered&&g.registered!==true)issues.push('UNCONFIRMED_REGISTRATION_ASSERTION');
  if(o.customer_vehicle_relation==='trade_in'&&g.customer_vehicle_purpose==='independent_sale')issues.push('SALE_IS_NOT_ENTRY');
  if(o.vehicle_entry_discussed&&g.vehicle_entry_discussion_allowed===false)issues.push('UNAUTHORIZED_ENTRY_DISCUSSION');
  if(o.sale_as_entry&&g.customer_sale&&g.trade_in_status!=='offered')issues.push('SALE_IS_NOT_ENTRY');
  if(['approved','rejected'].includes(o.commercial_decision))issues.push('UNAUTHORIZED_COMMERCIAL_DECISION');
  if(o.asks_cash_deposit&&g.vehicle_entry_discussion_allowed!==false&&['policy_discussed','offered'].includes(g.trade_in_status))issues.push('IGNORED_VEHICLE_ENTRY');
  if(o.asks_name&&g.customer_name)issues.push('ALREADY_VALIDATED_NAME');
  if(o.asks_purchase_selection&&g.selected_product&&!g.purchase_clarification)issues.push('REASKED_SELECTED_PRODUCT');
  if(o.asks_entry_details&&g.entry_context===false)issues.push('UNREQUESTED_ENTRY_QUESTION');
  if(o.asks_entry_details&&g.assigned===true)issues.push('COLLECTING_AFTER_HANDOFF');
  if(o.vehicle_price_cents!==null&&o.vehicle_price_cents!==undefined){
