    }
  }
  if (settings.ai_enabled !== true || lead?.ai_locked || control.lockedByHuman) {
    if (!await commit()) return {ok:true,skipped:true};
    Object.assign(event,{handoff:!!(lead?.ai_locked||control.lockedByHuman),stage:lead?.stage_key||'Atendimento humano',ai_provider:'sales_lock'});
    await saveEvent(event);await complete('done');return {ok:true,skipped:true,human_lock:event.handoff};
  }
  // Transcribe before ALL commercial intent and inventory/lead decisions.
  // Otherwise those checks see '[audio]' instead of the spoken message.
  try {
    await transcribeTurnAudio(context);
  } catch (error) {
    if (!await commit()) return {ok:true,skipped:true,reason:'superseded'};
    if(tenantSlug==='wesley_automoveis'){
      const retryState={...salesMergeState(lead?.state||{},{}),follow_up_disposition:'not_applicable',optional_human_offer:null};
      const retryStage=lead?.stage_key&&cfg.stages[lead.stage_key]?.allow_ai===true?lead.stage_key:cfg.stage_keys.qualifying;
      let retryLead;
      try{
        retryLead=await supabasePost('/rest/v1/rpc/magia_sales_save',{
          p_tenant:context.tenant.id,p_chat:chatId,p_session:turn.boundary_id,p_token:turn.token,
          p_revision:lead?.revision||0,p_request:turn.messages.at(-1).event_id,
          p_state:retryState,p_product:lead?.product||null,p_stage:retryStage,p_register:false,p_documents:[]});
      }catch(error){
        if(/SALES_CONTROL_CHANGED|STALE_SALES_/.test(String(error.message||''))){await complete('cancelled');return {ok:false,skipped:true,reason:'sales_control_changed'};}
        throw error;
      }
      Object.assign(event,{ai_provider:'audio_retry',service:'sales_qualification',stage:retryStage,handoff:false,
        ai_error:'AUDIO_TRANSCRIPTION_RETRY',raw_payload:{...(event.raw_payload||{}),sales_lead_id:retryLead.id,sales_revision:retryLead.revision,follow_up_disposition:'not_applicable'}});
