function referralText(value, max = 500) {
  const text = (typeof value === 'string' || (typeof value === 'number' && Number.isFinite(value))) ? String(value).trim() : '';
  return text.length > 0 && text.length <= max ? text : '';
}

function referralFromEvolution(raw = {}) {
  // Evolution has emitted externalAdReply in a few different wrapper shapes
  // across versions. Search only known message/context wrappers, with a hard
  // depth cap, so ad context is not lost before the Sales Core sees it.
  const root = raw && typeof raw === 'object' ? raw : {};
  const queue = [{ value: root, depth: 0 }];
  const seen = new Set();
  const wrapperKeys = [
    'data','message','contextInfo','messageContextInfo','quotedMessage',
    'ephemeralMessage','viewOnceMessage','viewOnceMessageV2','documentWithCaptionMessage',
    'extendedTextMessage','imageMessage','videoMessage','documentMessage','audioMessage',
    'buttonsResponseMessage','templateButtonReplyMessage','interactiveResponseMessage'
  ];
  let adReply = null;
  while (queue.length && !adReply) {
    const { value, depth } = queue.shift();
    if (!value || typeof value !== 'object' || seen.has(value) || depth > 6) continue;
    seen.add(value);
    if (value.externalAdReply && typeof value.externalAdReply === 'object') { adReply = value.externalAdReply; break; }
    if (value.contextInfo?.externalAdReply && typeof value.contextInfo.externalAdReply === 'object') { adReply = value.contextInfo.externalAdReply; break; }
    if (value.messageContextInfo?.externalAdReply && typeof value.messageContextInfo.externalAdReply === 'object') { adReply = value.messageContextInfo.externalAdReply; break; }
    for (const key of wrapperKeys) {
      const child = value[key];
      if (child && typeof child === 'object') queue.push({ value: child, depth: depth + 1 });
    }
  }
  if (!adReply) return null;
  const referral = { source: 'external_ad_reply' };
  const fields = [['title', 'title'], ['body', 'body'], ['sourceId', 'source_id'], ['sourceUrl', 'source_url'], ['mediaType', 'media_type']];
  for (const [from, to] of fields) {
    const value = referralText(adReply[from]);
    if (value) referral[to] = value;
  }
  return Object.keys(referral).length > 1 ? referral : null;
}

// A pergunta automatica do catalogo WhatsApp pode carregar produto citado em
// productMessage, referencedProduct ou quotedMessage, nao em externalAdReply.
// Guardamos somente ids/titulo: preco e foto devem vir do catalogo atual.
function catalogReferenceFromEvolution(raw = {}) {
  const queue=[{value:raw,depth:0}], seen=new Set();
  const wrappers=['data','message','contextInfo','messageContextInfo','quotedMessage',
    'extendedTextMessage','conversation','productMessage','ephemeralMessage',
    'viewOnceMessage','viewOnceMessageV2','interactiveResponseMessage','imageMessage'];
  while (queue.length) {
    const {value,depth}=queue.shift();
    if (!value||typeof value!=='object'||seen.has(value)||depth>7) continue;
    seen.add(value);
    const ref=value.productMessage?.product || value.productMessage?.productSnapshot
      || value.referencedProduct || value.contextInfo?.referencedProduct
      || value.messageContextInfo?.referencedProduct || null;
    if (ref && typeof ref==='object') {
      const productId=referralText(ref.productId||ref.product_id||ref.id,220);
      const retailerId=referralText(ref.retailerId||ref.retailer_id||ref.sku,220);
      const title=referralText(ref.title||ref.name,500);
      if (productId||retailerId||title) return {
        source:'whatsapp_catalog_product',product_id:productId,
        retailer_id:retailerId,title
      };
    }
    for (const key of wrappers) {
      const child=value[key];
      if (child && typeof child==='object') queue.push({value:child,depth:depth+1});
    }
  }
  return null;
}

