  const markdown = String(value).match(/\((https?:\/\/[^)]+)\)/);
  return (markdown ? markdown[1] : String(value)).trim().replace(/\/$/, '');
}
function invalid(value) {
  return !value || /COLE_AQUI|SEU_TOKEN|AJUSTAR/.test(value);
